def solve_near_trades(text):
    tokens = text.split()
    n, d = int(tokens[0]), int(tokens[1])
    times = [int(t) for t in tokens[2:2 + n]]
    count = 0
    left = 0
    for right in range(n):
        while times[right] - times[left] > d:
            left += 1
        count += right - left
    return str(count)
